-- ============================================================================
-- Nova RP Pedia: Каталог автосалона (34 авто + сводный список) с фото из полосы снизу
-- Запустите этот скрипт в Supabase -> SQL Editor -> Run
-- Повторный запуск безопасен: старые дубликаты в разделе transport заменяются
-- ============================================================================

begin;

insert into public.pedia_sections (slug, title, summary, icon, sort_order)
values ('transport', 'Транспорт', 'Автосалоны, реальные прототипы (IRL), гос. цены, фото и характеристики транспорта.', '⬡', 40)
on conflict (slug) do update
set title = excluded.title,
    summary = excluded.summary,
    icon = excluded.icon,
    sort_order = excluded.sort_order;

-- Удаляем прежние карточки этих моделей, чтобы обновить их версиями с фотографиями и IRL-названиями
delete from public.pedia_articles
where section_slug = 'transport'
  and title in (
    'Автосалон — сводный список',
    'Ubermacht X6 (M60I)',
    'Ubermacht M5 (E60)',
    'Benefactor-Benz 600SEL (W140)',
