    'Pegassi Huayara BC',
    'Bravado Coronet 440 1967',
    'Declasse Haveli',
    'Karin Mark 2',
    'Benefactor-MG C63 Coupe (W205)',
    'Coil Roadster',
    'Coil Model S',
    'Coil Model X',
    'Progen GT',
    'Ocelot Evija',
